import * as Sentry from "@sentry/nextjs/cloudflare";
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";
import { SENTRY_DATA_COLLECTION } from "./src/lib/sentry";

type Env = { SENTRY_DSN?: string; SENTRY_ENVIRONMENT?: string };

// The Worker entry (wrangler.jsonc `main`): OpenNext's handler with Sentry around it. SENTRY_DSN is a runtime variable
// of the Worker; without it nothing is sent. The release comes from the build (withSentryConfig in next.config.ts).
export default Sentry.withSentry(
  (env: Env) => ({
    dsn: env.SENTRY_DSN,
    environment: env.SENTRY_ENVIRONMENT || "production",
    dataCollection: SENTRY_DATA_COLLECTION,
    tracesSampleRate: 0.1,
  }),
  handler,
);
